solution.solution.lua:
function char_count(s)
    return utf8.len(s)
end

function reverse_text(s)
    local chars = {}
    for ch in s:gmatch(utf8.charpattern) do table.insert(chars, 1, ch) end
    return table.concat(chars)
end

function truncate(s, n)
    if utf8.len(s) <= n then return s end
    return s:sub(1, utf8.offset(s, n + 1) - 1) .. "…"
end

function is_ascii(s)
    return not s:find("[\128-\255]")
end
